function firstNumber(...values: unknown[]): number | undefined {
  for (const value of values) {
    if (typeof value === "number" && Number.isFinite(value)) {
      return value;
    }
  }
  return undefined;
}

function repositoryPath(repository: RepositoryDetail, path = ""): string {
  return `${repository.htmlUrl}${path}`;
}

function encodeRepositoryPath(path: string): string {
  return path.split("/").map(encodeURIComponent).join("/");
}

function repositoryPathForEntryType(
  repository: RepositoryDetail,
  path: string,
  entryType: "file" | "dir",
  ref = repository.defaultBranch ?? "HEAD"
): string {
  return repositoryPath(
    repository,
    `/${entryType === "dir" ? "tree" : "blob"}/${encodeURIComponent(ref)}/${encodeRepositoryPath(path)}`
  );
}

function parentDirectory(path: string): string {
  const parts = path.split("/").filter(Boolean);
  parts.pop();
  return parts.join("/");
}

function pathSegments(path: string): Array<{ label: string; path: string }> {
  const parts = path.split("/").filter(Boolean);
  return parts.map((label, index) => ({ label, path: parts.slice(0, index + 1).join("/") }));
}

interface MarkdownUrlContext {
  linkBaseUrl: string;
  linkRootUrl: string;
  imageBaseUrl: string;
  imageRootUrl: string;
  repositoryHtmlUrl?: string;
}

function safeExternalMarkdownUrl(
  url: string,
  context?: Pick<MarkdownUrlContext, "linkBaseUrl" | "linkRootUrl">
): string | null {
  return safeMarkdownUrl(url, context?.linkBaseUrl, context?.linkRootUrl);
}

function safeMarkdownImageUrl(
  url: string,
  context?: Pick<MarkdownUrlContext, "imageBaseUrl" | "imageRootUrl">
): string | null {
  return safeMarkdownUrl(url, context?.imageBaseUrl, context?.imageRootUrl);
}

function safeMarkdownUrl(url: string, baseUrl?: string, rootUrl?: string): string | null {
  try {
    const trimmedUrl = url.trim();
    const parsed =
      trimmedUrl.startsWith("/") && !trimmedUrl.startsWith("//") && rootUrl
        ? new URL(trimmedUrl.slice(1), rootUrl)
        : new URL(trimmedUrl, baseUrl);
    return parsed.protocol === "https:" ? parsed.toString() : null;
  } catch {
    return null;
  }
}

function trimMarkdownUrlToken(url: string): { url: string; suffix: string } {
  let safeUrl = url;
  let suffix = "";

  while (/[.,;:!?]$/.test(safeUrl)) {
    suffix = `${safeUrl.at(-1) ?? ""}${suffix}`;
    safeUrl = safeUrl.slice(0, -1);
  }

  return { url: safeUrl, suffix };
}

function normalizedSearchParts(value: string): string[] {
  return value.trim().toLowerCase().split(/\s+/).filter(Boolean);
}

function fieldsMatchSearchParts(fields: Array<string | number | null | undefined>, parts: string[]): boolean {
  if (parts.length === 0) {
    return true;
  }

  const haystack = fields
    .filter((field): field is string | number => field !== null && field !== undefined)
    .map(String)
    .join(" ")
    .toLowerCase();

  return parts.every((part) => haystack.includes(part));
}

function markdownReferenceUrl(token: string, context?: MarkdownUrlContext): string | null {
  if (/^@[A-Za-z0-9-]+$/.test(token)) {
    return safeMarkdownUrl(`https://github.com/${token.slice(1)}`);
  }

  const issueReference = token.match(/^(?:([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+))?#(\d+)$/);
  if (!issueReference) {
    return null;
  }

  const repositoryPath =
    issueReference[1] ?? context?.repositoryHtmlUrl?.replace(/^https:\/\/github\.com\//, "");
  return repositoryPath
    ? safeMarkdownUrl(`https://github.com/${repositoryPath}/issues/${issueReference[2]}`)
    : null;
}

function markdownRepositoryUrlContext(
  repository: RepositoryDetail,
  ref: string,
  directoryPath = ""
): MarkdownUrlContext {
  const normalizedDirectory = directoryPath.split("/").filter(Boolean).map(encodeURIComponent).join("/");
  const encodedRef = encodeURIComponent(ref);
  const directorySuffix = normalizedDirectory ? `${normalizedDirectory}/` : "";

  return {
    linkBaseUrl: repositoryPath(repository, `/blob/${encodedRef}/${directorySuffix}`),
    linkRootUrl: repositoryPath(repository, `/blob/${encodedRef}/`),
    imageBaseUrl: `https://raw.githubusercontent.com/${repository.owner}/${repository.name}/${encodedRef}/${directorySuffix}`,
    imageRootUrl: `https://raw.githubusercontent.com/${repository.owner}/${repository.name}/${encodedRef}/`,
    repositoryHtmlUrl: repository.htmlUrl
  };
}

function markdownProjectUrlContext(
  project: ProjectSummary,
  repository: RepositoryDetail
): MarkdownUrlContext {
  const contextUrl =
    [project.htmlUrl, project.ownerHtmlUrl, repository.htmlUrl]
      .map((url) => (url ? safeMarkdownUrl(url) : null))
      .find((url): url is string => Boolean(url)) ?? repositoryPath(repository, "/");
  const contextBaseUrl = contextUrl.endsWith("/") ? contextUrl : `${contextUrl}/`;

  return {
    linkBaseUrl: contextBaseUrl,
    linkRootUrl: contextBaseUrl,
    imageBaseUrl: contextBaseUrl,
    imageRootUrl: contextBaseUrl,
    repositoryHtmlUrl: repository.htmlUrl
  };
}

function markdownOrganizationProjectUrlContext(project: ProjectSummary): MarkdownUrlContext {
  const contextUrl =
    [project.htmlUrl, project.ownerHtmlUrl]
      .map((url) => (url ? safeMarkdownUrl(url) : null))
      .find((url): url is string => Boolean(url)) ?? "https://github.com/";
  const contextBaseUrl = contextUrl.endsWith("/") ? contextUrl : `${contextUrl}/`;

  return {
    linkBaseUrl: contextBaseUrl,
    linkRootUrl: contextBaseUrl,
    imageBaseUrl: contextBaseUrl,
    imageRootUrl: contextBaseUrl,
    repositoryHtmlUrl: project.ownerHtmlUrl ?? contextBaseUrl
  };
}

function markdownWikiUrlContext(
  repository: RepositoryDetail,
  pagePath: string,
  pageHtmlUrl: string | null | undefined
): MarkdownUrlContext {
  const normalizedDirectory = parentDirectory(pagePath)
    .split("/")
    .filter(Boolean)
    .map(encodeURIComponent)
    .join("/");
  const directorySuffix = normalizedDirectory ? `${normalizedDirectory}/` : "";
  const owner = encodeURIComponent(repository.owner);
  const repo = encodeURIComponent(repository.name);

  return {
    linkBaseUrl: pageHtmlUrl ?? repositoryPath(repository, "/wiki/"),
    linkRootUrl: repositoryPath(repository, "/wiki/"),
    imageBaseUrl: `https://raw.githubusercontent.com/${owner}/${repo}.wiki/HEAD/${directorySuffix}`,
    imageRootUrl: `https://raw.githubusercontent.com/${owner}/${repo}.wiki/HEAD/`,
    repositoryHtmlUrl: repository.htmlUrl
  };
}

function splitTableCells(line: string): string[] {
  return line
    .replace(/^\s*\|?/, "")
    .replace(/\|?\s*$/, "")
    .split("|")
    .map((cell) => cell.trim());
}

function isMarkdownTableDivider(line: string): boolean {
  return /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);
}

function markdownBlockKey(prefix: string, lineNumber: number, content: string): string {
  return `${prefix}-${lineNumber}-${content.slice(0, 80)}`;
}

function renderPlainMarkdownText(
  text: string,
  keyPrefix: string,
  onOpenExternal: (url: string) => void,
  onOpenMarkdownUrl?: MarkdownUrlHandler,
  urlContext?: MarkdownUrlContext,
  interactiveReferences = true
): ReactNode[] {
  const nodes: ReactNode[] = [];
  const tokenPattern = /(https:\/\/[^\s<>()\]]+|@[A-Za-z0-9-]+|(?:[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+)?#\d+)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = tokenPattern.exec(text))) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }

    const token = match[0];
    if (interactiveReferences && token.startsWith("https://")) {
      const trimmed = trimMarkdownUrlToken(token);
      const safeUrl = safeMarkdownUrl(trimmed.url);
      if (safeUrl) {
        nodes.push(
          <button
            className="markdown-link"
            key={`${keyPrefix}-autolink-${match.index}`}
            type="button"
            onClick={() => (onOpenMarkdownUrl ?? onOpenExternal)(safeUrl)}
          >
            {trimmed.url}
          </button>
        );
        if (trimmed.suffix) {
          nodes.push(trimmed.suffix);
        }
      } else {
        nodes.push(token);
      }
      lastIndex = match.index + token.length;
      continue;
    }

    const referenceUrl = interactiveReferences ? markdownReferenceUrl(token, urlContext) : null;
    nodes.push(
      referenceUrl ? (
        <button
          className="markdown-reference markdown-reference-button"
          key={`${keyPrefix}-ref-${match.index}`}
          type="button"
          onClick={() => (onOpenMarkdownUrl ?? onOpenExternal)(referenceUrl)}
        >
          {token}
        </button>
      ) : (
        <span className="markdown-reference" key={`${keyPrefix}-ref-${match.index}`}>
          {token}
        </span>
      )
    );
    lastIndex = match.index + token.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
}

function renderEmphasisMarkdown(
  text: string,
  keyPrefix: string,
  onOpenExternal: (url: string) => void,
  onOpenMarkdownUrl?: MarkdownUrlHandler,
  urlContext?: MarkdownUrlContext,
  interactiveReferences = true
): ReactNode[] {
  const nodes: ReactNode[] = [];
  const emphasisPattern = /(~~([^~]+)~~|\*\*([^*]+)\*\*|\*([^*]+)\*)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = emphasisPattern.exec(text))) {
    if (match.index > lastIndex) {
      nodes.push(
        ...renderPlainMarkdownText(
          text.slice(lastIndex, match.index),
          `${keyPrefix}-text-${lastIndex}`,
          onOpenExternal,
          onOpenMarkdownUrl,
          urlContext,
          interactiveReferences
        )
      );
    }
    const deletedText = match[2];
    const strongText = match[3];
    const emphasisText = match[4];
    nodes.push(
      deletedText ? (
        <del key={`${keyPrefix}-del-${match.index}`}>
          {renderPlainMarkdownText(
            deletedText,
            `${keyPrefix}-d`,
            onOpenExternal,
            onOpenMarkdownUrl,
            urlContext,
            interactiveReferences
          )}
        </del>
      ) : strongText ? (
        <strong key={`${keyPrefix}-strong-${match.index}`}>
          {renderPlainMarkdownText(
            strongText,
            `${keyPrefix}-s`,
            onOpenExternal,
            onOpenMarkdownUrl,
            urlContext,
            interactiveReferences
          )}
        </strong>
      ) : (
        <em key={`${keyPrefix}-em-${match.index}`}>
          {renderPlainMarkdownText(
            emphasisText,
            `${keyPrefix}-e`,
            onOpenExternal,
            onOpenMarkdownUrl,
            urlContext,
            interactiveReferences
          )}
        </em>
      )
    );
    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < text.length) {
    nodes.push(
      ...renderPlainMarkdownText(
        text.slice(lastIndex),
        `${keyPrefix}-text-${lastIndex}`,
        onOpenExternal,
        onOpenMarkdownUrl,
        urlContext,
        interactiveReferences
      )
    );
  }

  return nodes;
}

function renderInlineMarkdown(
  text: string,
  onOpenExternal: (url: string) => void,
  keyPrefix: string,
  urlContext?: MarkdownUrlContext,
  onOpenMarkdownUrl?: MarkdownUrlHandler
): ReactNode[] {
  const nodes: ReactNode[] = [];
  const inlinePattern = /(`([^`]+)`|!\[([^\]]*)\]\(([^)\s]+)\)|\[([^\]]+)\]\(([^)\s]+)\))/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = inlinePattern.exec(text))) {
    if (match.index > lastIndex) {
      nodes.push(
        ...renderEmphasisMarkdown(
          text.slice(lastIndex, match.index),
          `${keyPrefix}-text-${lastIndex}`,
          onOpenExternal,
          onOpenMarkdownUrl,
          urlContext
        )
      );
    }

    if (match[2]) {
      nodes.push(<code key={`${keyPrefix}-code-${match.index}`}>{match[2]}</code>);
    } else if (match[4] !== undefined) {
      const safeUrl = safeMarkdownImageUrl(match[4], urlContext);
      nodes.push(
        safeUrl ? (
          <img
            alt={match[3]}
            className="markdown-image"
            key={`${keyPrefix}-image-${match.index}`}
            loading="lazy"
            referrerPolicy="no-referrer"
            src={safeUrl}
          />
        ) : (
          <span className="markdown-unsafe" key={`${keyPrefix}-image-${match.index}`}>
            {match[3] || "Unsafe image"}
          </span>
        )
      );
    } else if (match[6] !== undefined) {
      const safeUrl = safeExternalMarkdownUrl(match[6], urlContext);
      nodes.push(
        safeUrl ? (
          <button
            className="markdown-link"
            key={`${keyPrefix}-link-${match.index}`}
            type="button"
            onClick={() => (onOpenMarkdownUrl ?? onOpenExternal)(safeUrl)}
          >
            {renderEmphasisMarkdown(
              match[5],
              `${keyPrefix}-link-label-${match.index}`,
              onOpenExternal,
              onOpenMarkdownUrl,
              urlContext,
              false
            )}
          </button>
        ) : (
          <span className="markdown-unsafe" key={`${keyPrefix}-link-${match.index}`}>
            {match[5]}
          </span>
        )
      );
    }

    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < text.length) {
    nodes.push(
      ...renderEmphasisMarkdown(
        text.slice(lastIndex),
        `${keyPrefix}-text-${lastIndex}`,
        onOpenExternal,
        onOpenMarkdownUrl,
        urlContext
      )
    );
  }

  return nodes;
}

function MarkdownBody({
  markdown,
  onOpenExternal,
  onOpenMarkdownUrl,
  urlContext,
  emptyText = "No markdown content."
}: {
  markdown: string | null | undefined;
  onOpenExternal(url: string): void;
  onOpenMarkdownUrl?: MarkdownUrlHandler;
  urlContext?: MarkdownUrlContext;
  emptyText?: string;
}): JSX.Element {
  const contextMarkdownUrlHandler = use(MarkdownUrlHandlerContext);
  const markdownUrlHandler = onOpenMarkdownUrl ?? contextMarkdownUrlHandler ?? undefined;
  const lines = (markdown?.trim() || emptyText).split(/\r?\n/);
  const blocks: ReactNode[] = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index] ?? "";

    if (!line.trim()) {
      index += 1;
      continue;
    }

    const fence = line.match(/^```([A-Za-z0-9_-]+)?\s*$/);
    if (fence) {
      const blockStartLine = index;
      const codeLines: string[] = [];
      index += 1;
      while (index < lines.length && !/^```\s*$/.test(lines[index] ?? "")) {
        codeLines.push(lines[index] ?? "");
        index += 1;
      }
      index += 1;
      blocks.push(
        <pre
          className="markdown-code-block"
          key={markdownBlockKey("code", blockStartLine, codeLines.join("\n"))}
        >
          {fence[1] && <span>{fence[1]}</span>}
          <code>{codeLines.join("\n")}</code>
        </pre>
      );
      continue;
    }

    const heading = line.match(/^(#{1,4})\s+(.+)$/);
    if (heading) {
      const blockStartLine = index;
      const level = Math.min(heading[1].length + 2, 6);
      const Tag = `h${level}` as keyof JSX.IntrinsicElements;
      blocks.push(
        <Tag key={markdownBlockKey("heading", blockStartLine, heading[2].trim())}>
          {renderInlineMarkdown(
            heading[2].trim(),
            onOpenExternal,
            `heading-${blockStartLine}`,
            urlContext,
            markdownUrlHandler
          )}
        </Tag>
      );
      index += 1;
      continue;
    }

    if (index + 1 < lines.length && line.includes("|") && isMarkdownTableDivider(lines[index + 1] ?? "")) {
      const blockStartLine = index;
      const headers = splitTableCells(line);
      const rows: string[][] = [];
      index += 2;
      while (index < lines.length && lines[index]?.includes("|")) {
        rows.push(splitTableCells(lines[index] ?? ""));
        index += 1;
      }
      blocks.push(
        <table className="markdown-table" key={markdownBlockKey("table", blockStartLine, line)}>
          <thead>
            <tr>
              {headers.map((header, cellIndex) => (
                <th key={`h-${header}`}>
                  {renderInlineMarkdown(
                    header,
                    onOpenExternal,
                    `table-h-${index}-${cellIndex}`,
                    urlContext,
                    markdownUrlHandler
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIndex) => (
              <tr key={`r-${row.join("|")}`}>
                {headers.map((_, cellIndex) => (
                  <td key={`c-${headers[cellIndex] ?? ""}`}>
                    {renderInlineMarkdown(
                      row[cellIndex] ?? "",
                      onOpenExternal,
                      `table-c-${index}-${rowIndex}-${cellIndex}`,
                      urlContext,
                      markdownUrlHandler
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      );
      continue;
    }

    const unordered = line.match(/^\s*[-*]\s+(?:\[([ xX])\]\s+)?(.+)$/);
    const ordered = line.match(/^\s*\d+\.\s+(.+)$/);
    if (unordered || ordered) {
      const blockStartLine = index;
      const items: Array<{ checked: boolean | null; lineNumber: number; text: string }> = [];
      const orderedList = Boolean(ordered);
      while (index < lines.length) {
        const itemLineNumber = index;
        const current = lines[index] ?? "";
        const unorderedItem = current.match(/^\s*[-*]\s+(?:\[([ xX])\]\s+)?(.+)$/);
        const orderedItem = current.match(/^\s*\d+\.\s+(.+)$/);
        if ((orderedList && !orderedItem) || (!orderedList && !unorderedItem)) {
          break;
        }
        items.push({
          checked: unorderedItem?.[1] ? unorderedItem[1].toLowerCase() === "x" : null,
          lineNumber: itemLineNumber,
          text: (orderedItem?.[1] ?? unorderedItem?.[2] ?? "").trim()
        });
        index += 1;
      }
      const ListTag = orderedList ? "ol" : "ul";
      blocks.push(
        <ListTag
          className={items.some((item) => item.checked !== null) ? "markdown-task-list" : undefined}
          key={markdownBlockKey("list", blockStartLine, items.map((item) => item.text).join("\n"))}
        >
          {items.map((item) => (
            <li key={markdownBlockKey("item", item.lineNumber, item.text)}>
              {item.checked !== null && <input checked={item.checked} readOnly type="checkbox" />}
              {renderInlineMarkdown(
                item.text,
                onOpenExternal,
                `list-${blockStartLine}-${item.lineNumber}`,
                urlContext,
                markdownUrlHandler
              )}
            </li>
          ))}
        </ListTag>
      );
      continue;
    }

    if (line.startsWith(">")) {
      const blockStartLine = index;
      const quoteLines: string[] = [];
      while (index < lines.length && lines[index]?.startsWith(">")) {
        quoteLines.push((lines[index] ?? "").replace(/^>\s?/, ""));
        index += 1;
      }
      blocks.push(
        <blockquote key={markdownBlockKey("quote", blockStartLine, quoteLines.join(" "))}>
          {renderInlineMarkdown(
            quoteLines.join(" "),
            onOpenExternal,
            `quote-${blockStartLine}`,
            urlContext,
            markdownUrlHandler
          )}
        </blockquote>
      );
      continue;
    }

    const paragraphLines: string[] = [];
    const blockStartLine = index;
    while (
      index < lines.length &&
      lines[index]?.trim() &&
      !/^```/.test(lines[index] ?? "") &&
      !/^(#{1,4})\s+/.test(lines[index] ?? "") &&
      !/^\s*[-*]\s+/.test(lines[index] ?? "") &&
      !/^\s*\d+\.\s+/.test(lines[index] ?? "") &&
      !/^>/.test(lines[index] ?? "")
    ) {
      paragraphLines.push(lines[index] ?? "");
      index += 1;
    }
    blocks.push(
      <p key={markdownBlockKey("paragraph", blockStartLine, paragraphLines.join(" "))}>
        {renderInlineMarkdown(
          paragraphLines.join(" "),
          onOpenExternal,
          `paragraph-${blockStartLine}`,
          urlContext,
          markdownUrlHandler
        )}
      </p>
    );
  }

  return <div className="markdown-body-lite">{blocks}</div>;
}

function repositoryMutationDisabledReason(repository: RepositoryDetail): string | null {
  if (repository.permissions.isDisabled) {
    return "Repository is disabled.";
  }
  if (repository.permissions.isArchived) {
    return "Repository is archived.";
  }
  return null;
}

function conversationCommentDisabledReason(
  repository: RepositoryDetail,
  locked: boolean | null | undefined
): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (locked) {
    return "Conversation is locked.";
  }
  return null;
}

function repositorySettingsMutationDisabledReason(repository: RepositoryDetail): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (repository.administration.viewerPermissions.admin !== true) {
    return "Repository settings require admin access.";
  }
  return null;
}

function unknownableCompactNumber(value: number | null | undefined): string {
  return value === null || value === undefined ? "unknown" : formatCompactNumber(value);
}

function repositoryForkMetadataLabel(repository: RepositoryRef): string {
  const visibility =
    repository.visibility ??
    (repository.isPrivate === null || repository.isPrivate === undefined
      ? "unknown visibility"
      : repository.isPrivate
        ? "private"
        : "public");
  const permission = repository.viewerPermission ?? "unknown permission";

  return [
    visibility.toLowerCase(),
    `${unknownableCompactNumber(repository.stargazerCount)} stars`,
    `${unknownableCompactNumber(repository.forkCount)} forks`,
    permission.toLowerCase()
  ].join(" · ");
}

function repositoryStatusMutationDisabledReason(repository: RepositoryDetail): string | null {
  if (repository.permissions.isDisabled) {
    return "Repository is disabled.";
  }
  if (repository.administration.viewerPermissions.admin !== true) {
    return "Repository status changes require admin access.";
  }
  return null;
}

function githubNumericId(id: number | string): number | null {
  if (typeof id === "number" && Number.isFinite(id)) {
    return id;
  }
  if (typeof id === "string" && /^\d+$/.test(id)) {
    return Number(id);
  }
  return null;
}

function commaSeparatedValues(value: string): string[] {
  return Array.from(
    new Set(
      value
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    )
  );
}

function appendCommaSeparatedValue(current: string, value: string): string {
  const values = commaSeparatedValues(current);
  if (!values.some((item) => item.toLowerCase() === value.toLowerCase())) {
    values.push(value);
  }
  return values.join(", ");
}

function mergeUniqueStrings(existing: string[], additions: string[]): string[] {
  const values = [...existing];
  for (const addition of additions) {
    if (!values.some((value) => value.toLowerCase() === addition.toLowerCase())) {
      values.push(addition);
    }
  }
  return values;
}

function commentMutationDisabledReason(
  repository: RepositoryDetail,
  comment: TimelineCommentSummary
): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (githubNumericId(comment.id) === null) {
    return "Comment id is unavailable for this action.";
  }
  return null;
}

function reviewCommentMutationDisabledReason(
  repository: RepositoryDetail,
  comment: PullRequestReviewThreadCommentSummary
): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (githubNumericId(comment.id) === null) {
    return "Review comment id is unavailable for this action.";
  }
  return null;
}

function mergeDisabledReason(repository: RepositoryDetail, pull: PullRequestSummary): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (pull.merged) {
    return "Pull request is already merged.";
  }
  if (pull.state !== "open") {
    return "Pull request is not open.";
  }
  if (pull.isDraft) {
    return "Draft pull requests cannot be merged.";
  }
  if (pull.mergeableState && pull.mergeableState !== "clean") {
    return `Merge is blocked because GitHub reports ${pull.mergeableState}.`;
  }
  return null;
}

function pullStateMutationDisabledReason(
  repository: RepositoryDetail,
  pull: PullRequestSummary
): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (pull.merged) {
    return "Merged pull requests cannot be reopened.";
  }
  return null;
}

function reviewDisabledReason(repository: RepositoryDetail, pull: PullRequestSummary): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (pull.locked) {
    return "Pull request conversation is locked.";
  }
  if (pull.state !== "open") {
    return "Pull request is not open.";
  }
  return null;
}

function workflowRerunDisabledReason(repository: RepositoryDetail, run: WorkflowRunSummary): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (run.actionAvailability?.canRerun === false) {
    return run.actionAvailability.rerunUrl
      ? "Only completed workflow runs can be rerun."
      : "GitHub did not return a workflow rerun endpoint.";
  }
  if (run.actionAvailability?.canRerun === true) {
    return null;
  }
  if (run.status !== "completed") {
    return "Only completed workflow runs can be rerun.";
  }
  return null;
}

function workflowFailedJobsRerunDisabledReason(
  repository: RepositoryDetail,
  run: WorkflowRunSummary
): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (run.actionAvailability?.canRerunFailedJobs === false) {
    return run.actionAvailability.rerunFailedJobsUrl
      ? "Only failed workflow runs can rerun failed jobs."
      : "GitHub did not return a failed-job rerun endpoint.";
  }
  if (run.actionAvailability?.canRerunFailedJobs === true) {
    return null;
  }
  if (run.status !== "completed") {
    return "Only completed workflow runs can be rerun.";
  }
  if (run.conclusion !== "failure") {
    return "Only failed workflow runs can rerun failed jobs.";
  }
  return null;
}

function workflowJobRerunDisabledReason(
  repository: RepositoryDetail,
  job: WorkflowRunJobSummary
): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (job.status !== "completed") {
    return "Only completed workflow jobs can be rerun.";
  }
  return null;
}

function workflowCancelDisabledReason(repository: RepositoryDetail, run: WorkflowRunSummary): string | null {
  const repositoryReason = repositoryMutationDisabledReason(repository);
  if (repositoryReason) {
    return repositoryReason;
  }
  if (run.actionAvailability?.canCancel === false) {
    return run.actionAvailability.cancelUrl
      ? "Completed workflow runs cannot be canceled."
      : "GitHub did not return a workflow cancel endpoint.";
  }
  if (run.actionAvailability?.canCancel === true) {
    return null;
  }
  if (run.status === "completed") {
    return "Completed workflow runs cannot be canceled.";
  }
  return null;
}

function workflowActionAvailabilityLabel(value: boolean | null | undefined): string {
  if (value === true) {
    return "available";
  }
  if (value === false) {
    return "unavailable";
  }
  return "unknown";
}

type WorkflowDispatchInputValues = Record<string, string | boolean>;

function workflowInputDefaults(inputs: WorkflowDispatchInputSummary[]): WorkflowDispatchInputValues {
  return inputs.reduce<WorkflowDispatchInputValues>((values, input) => {
    if (input.type === "boolean") {
      values[input.name] = input.defaultValue?.toLowerCase() === "true";
    } else {
      values[input.name] = input.defaultValue ?? "";
    }
    return values;
  }, {});
}

function workflowDispatchInputsPayload(
  inputs: WorkflowDispatchInputSummary[],
  values: WorkflowDispatchInputValues
): Record<string, string | boolean> {
  return inputs.reduce<Record<string, string | boolean>>((payload, input) => {
    const value = values[input.name];
    if (input.type === "boolean") {
      payload[input.name] = Boolean(value);
    } else if (typeof value === "string" && value.trim()) {
      payload[input.name] = value.trim();
    }
    return payload;
  }, {});
}

type WorkflowFailureSummaryItem = {
  id: string;
  kind: "Run" | "Job" | "Step" | "Check" | "Annotation";
  title: string;
  detail: string;
  state: string;
  url?: string | null;
  jobId?: number;
  path?: string | null;
  line?: number | null;
};

const workflowFailureStates = new Set([
  "failure",
  "cancelled",
  "timed_out",
  "startup_failure",
  "action_required"
]);
const workflowAttentionConclusions = new Set(["failure", "timed_out", "action_required", "cancelled"]);
const workflowAttentionStatuses = new Set(["in_progress", "queued", "waiting", "requested"]);

function isWorkflowFailureState(value: string | null | undefined): boolean {
  return Boolean(value && workflowFailureStates.has(value));
}

function isWorkflowRunAttention(run: Pick<WorkflowRunSummary, "conclusion" | "status">): boolean {
  const conclusion = run.conclusion?.toLowerCase();
  const status = run.status?.toLowerCase();
  return (
    Boolean(conclusion && workflowAttentionConclusions.has(conclusion)) ||
    Boolean(status && workflowAttentionStatuses.has(status))
  );
}

function compactWorkflowFailureText(value: string | null | undefined, fallback: string): string {
  const text = value?.replace(/\s+/g, " ").trim();
  if (!text) {
    return fallback;
  }
  return text.length > 180 ? `${text.slice(0, 177)}...` : text;
}

function workflowFailureSummary(detail: WorkflowRunDetail | undefined): WorkflowFailureSummaryItem[] {
  if (!detail) {
    return [];
  }

  const items: WorkflowFailureSummaryItem[] = [];
  const addItem = (item: WorkflowFailureSummaryItem): void => {
    if (items.length < 8) {
      items.push(item);
    }
  };

  detail.jobs.forEach((job) => {
    const jobState = job.conclusion ?? job.status ?? "unknown";
    if (isWorkflowFailureState(jobState)) {
      addItem({
        id: `job-${job.id}`,
        kind: "Job",
        title: job.name,
        detail: `${job.runnerName ?? "GitHub runner"} reported ${jobState}.`,
        state: jobState,
        url: job.htmlUrl,
        jobId: job.id
      });
    }

    job.steps
      .filter((step) => isWorkflowFailureState(step.conclusion ?? step.status))
      .slice(0, 2)
      .forEach((step) => {
        const stepState = step.conclusion ?? step.status ?? "unknown";
        addItem({
          id: `step-${job.id}-${step.number}`,
          kind: "Step",
          title: step.name,
          detail: `${job.name} step ${step.number} reported ${stepState}.`,
          state: stepState,
          url: job.htmlUrl,
          jobId: job.id
        });
      });
  });

  detail.checkRuns.forEach((checkRun) => {
    const checkState = checkRun.conclusion ?? checkRun.status ?? "unknown";
    if (isWorkflowFailureState(checkState)) {
      addItem({
        id: `check-${checkRun.id}`,
        kind: "Check",
        title: checkRun.name,
        detail: compactWorkflowFailureText(
          checkRun.outputTitle ?? checkRun.outputSummary ?? checkRun.outputText,
          `${checkRun.appName ?? "GitHub Checks"} reported ${checkState}.`
        ),
        state: checkState,
        url: checkRun.detailsUrl ?? checkRun.htmlUrl
      });
    }

    checkRun.annotations
      .filter(
        (annotation) => annotation.annotationLevel === "failure" || annotation.annotationLevel === "warning"
      )
      .slice(0, 2)
      .forEach((annotation, index) => {
        addItem({
          id: `annotation-${checkRun.id}-${annotation.path}-${annotation.startLine ?? index}`,
          kind: "Annotation",
          title: annotation.title ?? checkRun.name,
          detail: compactWorkflowFailureText(
            annotation.message,
            `${annotation.path}${annotation.startLine ? `:${annotation.startLine}` : ""}`
          ),
          state: annotation.annotationLevel ?? "annotation",
          url: annotation.blobHref,
          path: annotation.path,
          line: annotation.startLine
        });
      });
  });

  if (items.length === 0 && isWorkflowFailureState(detail.conclusion)) {
    addItem({
      id: `run-${detail.id}`,
      kind: "Run",
      title: detail.name,
      detail: "GitHub did not return failed jobs, checks, or annotations for this run.",
      state: detail.conclusion ?? "failed",
      url: detail.htmlUrl
    });
  }

  return items;
}

function workflowDispatchDisabledReason(
  workflow: WorkflowDefinitionSummary | null,
  workflowId: string,
  ref: string,
  values: WorkflowDispatchInputValues
): string | null {
  if (!workflowId.trim()) {
    return "Workflow dispatch requires a workflow file, name, or id.";
  }
  if (!ref.trim()) {
    return "Workflow dispatch requires a branch or tag.";
  }
  if (workflow && !workflow.dispatchable) {
    return "Selected workflow does not define workflow_dispatch.";
  }

  const missingInput = workflow?.inputs.find((input) => {
    const value = values[input.name];
    return input.required && input.type !== "boolean" && !(typeof value === "string" && value.trim());
  });
  return missingInput ? `${missingInput.name} is required.` : null;
}

function readAvailabilityMessage(
  feature: string,
  availability: GitHubReadAvailability | null
): string | null {
  if (!availability || availability.status === "available") {
    return null;
  }

  const reason =
    availability.status === "feature_disabled"
      ? `${feature} is disabled or not enabled for this repository.`
      : availability.status === "not_loaded"
        ? `${feature} was not loaded.`
        : availability.status === "permission_denied"
          ? `The current GitHub token cannot access ${feature.toLowerCase()}.`
          : availability.status === "rate_limited"
            ? `GitHub rate-limited the ${feature.toLowerCase()} request.`
            : availability.status === "graphql_error"
              ? `GitHub returned a GraphQL error for ${feature.toLowerCase()}.`
              : `${feature} could not be loaded.`;

  return availability.message ? `${reason} ${availability.message}` : reason;
}

function readAvailabilityStatusLabel(availability: GitHubReadAvailability | null): string | null {
  if (!availability || availability.status === "available") {
    return null;
  }

  if (availability.status === "feature_disabled") {
    return "not enabled";
  }
  if (availability.status === "not_loaded") {
    return "not loaded";
  }
  if (availability.status === "permission_denied") {
    return "no access";
  }
  if (availability.status === "rate_limited") {
    return "rate limited";
  }
  if (availability.status === "graphql_error") {
    return "GraphQL error";
  }

  return "unavailable";
}

function getRepositoryCounts(
  repository: RepositoryDetail,
  fallback: {
    issues: IssueSummary[];
    pulls: PullRequestSummary[];
    discussions: DiscussionSummary[];
    projects: ProjectSummary[];
    releases?: ReleaseSummary[];
  }
): Record<
  "stars" | "forks" | "watchers" | "issues" | "pulls" | "discussions" | "projects" | "releases",
  number
> {
  const parityRepository = repository as RepositoryWithParity;
  const counts = parityRepository.counts ?? {};

  return {
    stars: firstNumber(counts.stars, counts.stargazers, repository.stargazerCount) ?? 0,
    forks: firstNumber(counts.forks, repository.forkCount) ?? 0,
    watchers: firstNumber(counts.watchers, repository.watcherCount) ?? 0,
    issues:
      firstNumber(counts.openIssues, counts.issues, repository.openIssuesCount, fallback.issues.length) ?? 0,
    pulls: firstNumber(counts.openPullRequests, counts.pullRequests, fallback.pulls.length) ?? 0,
    discussions: firstNumber(counts.discussions, fallback.discussions.length) ?? 0,
    projects: firstNumber(counts.projects, fallback.projects.length) ?? 0,
    releases: firstNumber(counts.releases, fallback.releases?.length) ?? 0
  };
}

function getViewerRepositoryState(repository: RepositoryDetail): {
  isStarred: boolean;
  isWatching: boolean;
  permission: string | null;
  canSubscribe: boolean | null;
} {
  const parityRepository = repository as RepositoryWithParity;
  const viewerState = parityRepository.viewerState ?? parityRepository.viewer;
  const subscription = viewerState?.subscription ?? parityRepository.viewerSubscription ?? null;
  const permission =
    viewerState?.permission ??
    viewerState?.viewerPermission ??
    parityRepository.viewerPermission ??
    parityRepository.permissions?.permission ??
    (parityRepository.permissions?.admin
      ? "admin"
      : parityRepository.permissions?.maintain
        ? "maintain"
        : parityRepository.permissions?.push
          ? "write"
          : parityRepository.permissions?.triage
            ? "triage"
            : parityRepository.permissions?.pull
              ? "read"
              : null);

  return {
    isStarred: Boolean(
      viewerState?.isStarred ?? viewerState?.hasStarred ?? parityRepository.viewerHasStarred
    ),
    isWatching: Boolean(
      viewerState?.isWatching ??
      (typeof subscription === "string" &&
        ["subscribed", "SUBSCRIBED", "watching", "WATCHING"].includes(subscription))
    ),
    permission,
    canSubscribe: viewerState?.canSubscribe ?? null
  };
}

function repositoryHeroMutationDisabledReason(
  repository: RepositoryDetail,
  viewerState: ReturnType<typeof getViewerRepositoryState>,
  action: "star" | "watch" | "fork",
  mutationPending: boolean
): string | null {
  if (mutationPending) {
    return "Another GitHub action is still running.";
  }
  if (repository.permissions.isDisabled) {
    return "Repository is disabled.";
  }
  if (action === "fork") {
    if (repository.permissions.isArchived) {
      return "Repository is archived.";
    }
    if (repository.administration.allowForking === false) {
      return "Forking is disabled for this repository.";
    }
  }
  if (action === "watch" && viewerState.canSubscribe === false) {
    return "This token cannot update repository watch state.";
  }
  return null;
}

