const previewableImageExtensions = new Set(["avif", "gif", "jpeg", "jpg", "png", "svg", "webp"]);
const markdownFileExtensions = new Set(["md", "markdown", "mdown", "mdx", "mkd"]);
const binaryFileExtensions = new Set([
  "7z",
  "avif",
  "bin",
  "bmp",
  "dmg",
  "exe",
  "gif",
  "gz",
  "ico",
  "jpeg",
  "jpg",
  "mov",
  "mp3",
  "mp4",
  "pdf",
  "png",
  "tar",
  "tgz",
  "webp",
  "woff",
  "woff2",
  "zip"
]);

function fileExtension(path: string): string | null {
  const name = path.toLowerCase().split("/").pop() ?? "";
  return name.includes(".") ? (name.split(".").pop() ?? null) : null;
}

function isPreviewableImagePath(path: string): boolean {
  const extension = fileExtension(path);
  return extension ? previewableImageExtensions.has(extension) : false;
}

function isMarkdownPath(path: string): boolean {
  const extension = fileExtension(path);
  return extension ? markdownFileExtensions.has(extension) : false;
}

function isReadmeMarkdownPath(path: string): boolean {
  return /^readme(?:\.[^.]+)?\.(?:md|markdown)$/i.test(path.split("/").pop() ?? "");
}

function isLikelyBinaryFile(path: string, content?: string | null): boolean {
  const extension = fileExtension(path);
  return Boolean(extension && binaryFileExtensions.has(extension)) || Boolean(content?.includes("\u0000"));
}

function iconUrlForEntry(entry: RepoEntry): string {
  if (entry.type === "dir") {
    const folderIcon = folderIconNames[entry.name.toLowerCase()] ?? "default_folder.svg";
    return `${vscodeIconsBaseUrl}/${folderIcon}`;
  }

  const lowerName = entry.name.toLowerCase();
  const fileNameIcon = fileNameIconNames[lowerName];
  if (fileNameIcon) {
    return `${vscodeIconsBaseUrl}/${fileNameIcon}`;
  }

  const extension = fileExtension(lowerName);
  return `${vscodeIconsBaseUrl}/${extension ? (extensionIconNames[extension] ?? "default_file.svg") : "default_file.svg"}`;
}

function EntryIcon({ entry }: { entry: RepoEntry }): JSX.Element {
  const iconUrl = useMemo(() => iconUrlForEntry(entry), [entry]);
  const [failedUrl, setFailedUrl] = useState<string | null>(null);
  const [loadedUrl, setLoadedUrl] = useState<string | null>(null);
  const failed = failedUrl === iconUrl;
  const loaded = loadedUrl === iconUrl;

  return (
    <span className="file-icon-wrap">
      {(!loaded || failed) && (entry.type === "dir" ? <Folder size={18} /> : <FileIcon size={17} />)}
      {!failed && (
        <img
          className={`file-type-icon ${loaded ? "loaded" : ""}`}
          src={iconUrl}
          alt=""
          aria-hidden="true"
          loading="lazy"
          onLoad={() => setLoadedUrl(iconUrl)}
          onError={() => setFailedUrl(iconUrl)}
        />
      )}
    </span>
  );
}

function entryFallbackAction(entry: RepoEntry): string {
  return entry.type === "dir" ? "Open folder" : "Open file";
}

function entryLastChangeLabel(entry: RepoEntry): string {
  if (entry.lastCommitAvailability.status !== "available") {
    if (entry.lastCommitAvailability.status === "not_loaded") {
      return "Last change not loaded";
    }
    return "Last change unavailable";
  }

  const message = entry.lastCommitMessage ?? entryFallbackAction(entry);
  const attribution = entry.lastCommitAuthorLogin ? `${message} by ${entry.lastCommitAuthorLogin}` : message;
  const changeSummary = fileCommitChangeSummary(entry);
  return changeSummary ? `${attribution} · ${changeSummary}` : attribution;
}

function entryBrowseTitle(entry: RepoEntry): string {
  const parts = [`Browse ${entry.path}`];

  if (entry.lastCommitAvailability.status !== "available") {
    const message = readAvailabilityMessage("File last change", entry.lastCommitAvailability);
    if (message) {
      parts.push(message);
    }
    return parts.join(" · ");
  }

  if (entry.lastCommitSha) {
    parts.push(`last changed in ${entry.lastCommitSha.slice(0, 7)}`);
  }
  if (entry.lastCommitAuthorLogin) {
    parts.push(`by ${entry.lastCommitAuthorLogin}`);
  }
  const changeSummary = fileCommitChangeSummary(entry);
  if (changeSummary) {
    parts.push(changeSummary);
  }

  return parts.join(" · ");
}

function fileCommitChangeSummary(file: RepoFileContent | RepoEntry | undefined): string | null {
  if (!file) {
    return null;
  }

  const parts = [
    file.lastCommitAdditions === null ? null : `+${file.lastCommitAdditions}`,
    file.lastCommitDeletions === null ? null : `-${file.lastCommitDeletions}`,
    file.lastCommitChanges === null ? null : `${file.lastCommitChanges} changed`
  ].filter(Boolean);

  return parts.length > 0 ? parts.join(" ") : null;
}

function FileBlamePanel({
  blame,
  rangeLimit,
  loading,
  error,
  externalUrl,
  onExpandPreview,
  onOpenRange,
  onOpenCommit,
  onOpenExternal
}: {
  blame?: RepoFileBlameResult;
  rangeLimit: number;
  loading: boolean;
  error: Error | null;
  externalUrl?: string | null;
  onExpandPreview?(): void;
  onOpenRange?(range: RepoFileBlameRange): void;
  onOpenCommit?(commit: RepoFileBlameCommit): void;
  onOpenExternal(url: string): void;
}): JSX.Element {
  const ranges = blame?.ranges ?? [];
  const availabilityMessage = readAvailabilityMessage("File blame", blame?.availability ?? null);
  const canExpandPreview =
    Boolean(blame?.truncated) && rangeLimit < expandedFileBlameRangeLimit && Boolean(onExpandPreview);
  const blameStatus = loading
    ? ranges.length > 0
      ? `Refreshing ${ranges.length} ranges`
      : "Loading ranges"
    : error || availabilityMessage
      ? "Unavailable"
      : ranges.length === 0
        ? "No ranges"
        : blame?.truncated
          ? `${ranges.length}+ ranges`
          : `${ranges.length} ranges`;

  return (
    <section className="readme-panel file-blame-panel">
      <header>
        <Eye size={17} />
        <span>Blame</span>
        <span className="state-chip">{blameStatus}</span>
        <button
          type="button"
          disabled={!externalUrl}
          title={externalUrl ? undefined : "GitHub blame URL unavailable."}
          onClick={() => {
            if (externalUrl) {
              onOpenExternal(externalUrl);
            }
          }}
        >
          <ExternalLink size={14} /> Open GitHub fallback
        </button>
        {canExpandPreview && (
          <button type="button" onClick={() => onExpandPreview?.()}>
            <Eye size={14} /> Load 100 ranges
          </button>
        )}
      </header>
      {loading && ranges.length === 0 && <div className="loading-state">Loading blame ranges…</div>}
      {error && <div className="error-state">File blame unavailable: {error.message}</div>}
      {availabilityMessage && <div className="error-state">{availabilityMessage}</div>}
      {!loading && !error && !availabilityMessage && ranges.length === 0 && (
        <div className="empty-state">Blame loaded, but GitHub returned no ranges for this file.</div>
      )}
      {ranges.length > 0 && (
        <div className="blame-range-list">
          {ranges.map((range) =>
            onOpenRange || onOpenCommit ? (
              <div
                className="blame-range-row"
                key={`${range.startingLine}-${range.endingLine}-${range.commit.sha}`}
              >
                <strong>
                  Lines {range.startingLine}-{range.endingLine}
                </strong>
                <span>{range.commit.headline}</span>
                <small>
                  {range.commit.authorLogin ?? range.commit.authorName ?? "unknown"} ·{" "}
                  {formatRelativeDate(range.commit.committedDate ?? range.commit.authoredDate)}
                </small>
                <code>{range.commit.sha.slice(0, 7)}</code>
                <div className="blame-range-row-actions">
                  {onOpenRange ? (
                    <button type="button" onClick={() => onOpenRange(range)}>
                      Open file at commit
                    </button>
                  ) : null}
                  {onOpenCommit ? (
                    <button type="button" onClick={() => onOpenCommit(range.commit)}>
                      Open commit in Control
                    </button>
                  ) : null}
                  {range.commit.htmlUrl ? (
                    <button
                      type="button"
                      onClick={() => {
                        if (range.commit.htmlUrl) {
                          onOpenExternal(range.commit.htmlUrl);
                        }
                      }}
                    >
                      GitHub fallback
                    </button>
                  ) : null}
                </div>
              </div>
            ) : (
              <button
                type="button"
                key={`${range.startingLine}-${range.endingLine}-${range.commit.sha}`}
                disabled={!range.commit.htmlUrl}
                title={range.commit.htmlUrl ? undefined : "Commit URL unavailable."}
                onClick={() => range.commit.htmlUrl && onOpenExternal(range.commit.htmlUrl)}
              >
                <strong>
                  Lines {range.startingLine}-{range.endingLine}
                </strong>
                <span>{range.commit.headline}</span>
                <small>
                  {range.commit.authorLogin ?? range.commit.authorName ?? "unknown"} ·{" "}
                  {formatRelativeDate(range.commit.committedDate ?? range.commit.authoredDate)}
                </small>
                <code>{range.commit.sha.slice(0, 7)}</code>
              </button>
            )
          )}
        </div>
      )}
      {blame?.truncated && (
        <small className="action-disabled-note">
          {rangeLimit >= expandedFileBlameRangeLimit
            ? "Control is showing the first 100 blame ranges."
            : "Showing the first blame ranges only."}
        </small>
      )}
    </section>
  );
}

function CommitHistoryPanel({
  title,
  subtitle,
  commits,
  loading,
  error,
  availabilityMessage,
  externalUrl,
  currentLimit,
  openCommitLabel = "Open in Control",
  onExpandCommits,
  onOpenCommit,
  onOpenExternal
}: {
  title: string;
  subtitle: string;
  commits: RepositoryCommitSummary[];
  loading: boolean;
  error: Error | null;
  availabilityMessage?: string | null;
  externalUrl?: string | null;
  currentLimit: number;
  openCommitLabel?: string;
  onExpandCommits(): void;
  onOpenCommit?(commit: RepositoryCommitSummary): void;
  onOpenExternal(url: string): void;
}): JSX.Element {
  const commitsLimitHit = commits.length >= currentLimit;
  const canExpandCommits = commitsLimitHit && currentLimit < maxCommitHistoryLimit;
  const historyStatus = loading
    ? commits.length > 0
      ? `Refreshing ${commits.length} commits`
      : "Loading commits"
    : error
      ? "Unavailable"
      : availabilityMessage
        ? "Unavailable"
        : commits.length === 0
          ? "No commits"
          : canExpandCommits
            ? `${commits.length}+ commits`
            : `${commits.length} commits`;

  return (
    <section className="readme-panel commit-history-panel">
      <header>
        <GitBranch size={17} />
        <span>{title}</span>
        <small>{subtitle}</small>
        <span className="state-chip">{historyStatus}</span>
        <button
          type="button"
          disabled={!externalUrl}
          title={externalUrl ? undefined : "GitHub history URL unavailable."}
          onClick={() => {
            if (externalUrl) {
              onOpenExternal(externalUrl);
            }
          }}
        >
          <ExternalLink size={14} /> Open GitHub fallback
        </button>
      </header>
      {loading && commits.length === 0 && <div className="loading-state">Loading commits…</div>}
      {error && <div className="error-state">Commit history unavailable: {error.message}</div>}
      {!loading && !error && availabilityMessage && <div className="error-state">{availabilityMessage}</div>}
      {!loading && !error && !availabilityMessage && commits.length === 0 && (
        <div className="empty-state">History loaded, but GitHub returned no commits for this scope.</div>
      )}
      {commits.length > 0 && (
        <div className="commit-history-list">
          {commits.map((commit) =>
            onOpenCommit ? (
              <div className="commit-history-row" key={commit.sha}>
                {commit.authorAvatarUrl ? <img src={commit.authorAvatarUrl} alt="" /> : null}
                <span>
                  <strong>{commit.headline}</strong>
                  <small>
                    {commit.authorLogin ?? commit.authorName ?? "unknown"} · {commit.sha.slice(0, 7)}
                    {commit.verified ? " · verified" : ""}
                    {commit.parentCount > 1 ? ` · ${commit.parentCount} parents` : ""}
                  </small>
                </span>
                <time>{formatRelativeDate(commit.committedDate ?? commit.authoredDate)}</time>
                <div className="commit-history-row-actions">
                  <button type="button" onClick={() => onOpenCommit(commit)}>
                    {openCommitLabel}
                  </button>
                  <button
                    type="button"
                    disabled={!commit.htmlUrl}
                    title={commit.htmlUrl ? undefined : "Commit URL unavailable."}
                    onClick={() => commit.htmlUrl && onOpenExternal(commit.htmlUrl)}
                  >
                    GitHub fallback
                  </button>
                </div>
              </div>
            ) : (
              <button
                key={commit.sha}
                type="button"
                disabled={!commit.htmlUrl}
                title={commit.htmlUrl ? undefined : "Commit URL unavailable."}
                onClick={() => commit.htmlUrl && onOpenExternal(commit.htmlUrl)}
              >
                {commit.authorAvatarUrl ? <img src={commit.authorAvatarUrl} alt="" /> : null}
                <span>
                  <strong>{commit.headline}</strong>
                  <small>
                    {commit.authorLogin ?? commit.authorName ?? "unknown"} · {commit.sha.slice(0, 7)}
                    {commit.verified ? " · verified" : ""}
                    {commit.parentCount > 1 ? ` · ${commit.parentCount} parents` : ""}
                  </small>
                </span>
                <time>{formatRelativeDate(commit.committedDate ?? commit.authoredDate)}</time>
              </button>
            )
          )}
        </div>
      )}
      {canExpandCommits && (
        <div className="table-action-row">
          <button type="button" onClick={onExpandCommits}>
            Load more commits
          </button>
        </div>
      )}
      {!canExpandCommits && commitsLimitHit && (
        <div className="muted-row">Showing the first {currentLimit} commits returned by GitHub.</div>
      )}
    </section>
  );
}

function normalizeLanguageStats(repository: RepositoryDetail): LanguageStat[] {
  const parityRepository = repository as RepositoryWithParity;
  const rawLanguages = parityRepository.languages;

  if (Array.isArray(rawLanguages)) {
    const items = rawLanguages
      .map((language) => {
        if (!language || typeof language !== "object") {
          return null;
        }
        const item = language as {
          name?: unknown;
          color?: unknown;
          size?: unknown;
          percent?: unknown;
          percentage?: unknown;
        };
        if (typeof item.name !== "string") {
          return null;
        }

        return {
          name: item.name,
          color: typeof item.color === "string" ? item.color : null,
          size: firstNumber(item.size) ?? null,
          percentage: firstNumber(item.percentage, item.percent) ?? null
        };
      })
      .filter((language): language is LanguageStat => Boolean(language));

    const totalSize = items.reduce((total, language) => total + (language.size ?? 0), 0);
    return items.map((language) => ({
      ...language,
      percentage:
        language.percentage ??
        (language.size !== null && totalSize > 0 ? Math.max(1, (language.size / totalSize) * 100) : null)
    }));
  }

  if (rawLanguages && typeof rawLanguages === "object") {
    const graphLanguages = rawLanguages as {
      totalSize?: unknown;
      edges?: Array<{ size?: unknown; node?: { name?: unknown; color?: unknown } }>;
      nodes?: Array<{ name?: unknown; color?: unknown; size?: unknown }>;
    };
    const edges = Array.isArray(graphLanguages.edges) ? graphLanguages.edges : [];
    const totalSize =
      firstNumber(graphLanguages.totalSize) ??
      edges.reduce((total, edge) => total + (firstNumber(edge.size) ?? 0), 0);

    if (edges.length > 0) {
      return edges
        .map((edge) => {
          const name = edge.node?.name;
          if (typeof name !== "string") {
            return null;
          }
          const size = firstNumber(edge.size) ?? null;
          return {
            name,
            color: typeof edge.node?.color === "string" ? edge.node.color : null,
            size,
            percentage: size !== null && totalSize > 0 ? Math.max(1, (size / totalSize) * 100) : null
          };
        })
        .filter((language): language is LanguageStat => Boolean(language));
    }

    if (Array.isArray(graphLanguages.nodes)) {
      const nodeLanguages: LanguageStat[] = [];
      for (const node of graphLanguages.nodes) {
        if (typeof node.name === "string") {
          nodeLanguages.push({
            name: node.name,
            color: typeof node.color === "string" ? node.color : null,
            size: firstNumber(node.size) ?? null,
            percentage: null
          });
        }
      }
      return nodeLanguages;
    }
  }

  return repository.primaryLanguage
    ? [
        {
          name: repository.primaryLanguage.name,
          color: repository.primaryLanguage.color,
          size: null,
          percentage: 100
        }
      ]
    : [];
}

function languageTotalLabel(languages: LanguageStat[]): string | null {
  const total = languages.reduce((sum, language) => sum + (language.size ?? 0), 0);
  if (total <= 0) {
    return null;
  }

  return `${formatCompactNumber(total)} bytes`;
}

function routeTitle(route: AppRoute): string {
  switch (route.kind) {
    case "mailbox":
      return "Mailbox";
    case "repositories":
      return "Repositories";
    case "organizations":
      return "Organizations";
    case "repository":
      return route.nameWithOwner;
    case "codeBrowser":
      return `${route.nameWithOwner}/${route.path}`;
    case "home":
    default:
      return "Home";
  }
}

function queryKeyLogLabel(queryKey: readonly unknown[]): string {
  try {
    return JSON.stringify(queryKey);
  } catch {
    return String(queryKey[0] ?? "query");
  }
}

function logRendererLoading(message: string, metadata?: Record<string, unknown>): void {
  if (!controlRendererLoadingLogsEnabled) {
    return;
  }

  if (metadata) {
    console.info("[Control loading]", message, metadata);
    return;
  }

  console.info("[Control loading]", message);
}

