          onExpandSecretScanningAlerts={onExpandSecretScanningAlerts}
          onExpandRepositoryRulesets={onExpandRepositoryRulesets}
          onExpandRepositorySecurityAdvisories={onExpandRepositorySecurityAdvisories}
